/**
 * @method
 * @name MxGrid_2_OnDblClick
 * @description MxGrid_2 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.MxGrid_2_OnDblClick = function(row, colid) {
    try {
        if (colid === 'SAVE_FILE_NM') {
            const screnId = dts_noticeList.getCellData(row, "SCREN_ID");
            location.href = "/filedownload.do?SCREN_ID=" + screnId + "&gubun=35";
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF90400.MxGrid_2_OnDblClick" });
    }
};

/**
 * @method
 * @name bnt_Select_onclick
 * @description bnt_Select 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.bnt_Select_onclick = async function() {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF90400.bnt_Select_onclick" });
    }
};

/**
 * @method
 * @name keyword_onkeydown
 * @description keyword 키 입력 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.keyword_onkeydown = async function() {
    try {
        if (window.event.keyCode === "13") {
            await scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF90400.keyword_onkeydown" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    const KeyWord = keyword.getValue();
    const Condition1 = $c.cp.valueOfIndex(MxCombo_1, "VALUE", MxCombo_1.getSelectedIndex());
    // var Condition2 = MxDataSet_code1.NameString((cb_system_gbn.Index+1),"CD_VAL");
    url += "&SCREN_ID=" + "ULDSTF90400.gfm";
    url += "&keyword=" + KeyWord;
    url += "&Condition1=" + Condition1;
    url += "&Condition2=3";
    const sbmOptions = {
        id : "sbm_dts_noticeList",
        action : "/NoticeContent.do",
        ref : "",
        target : "dts_noticeList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

